import net.sf.jsqlparser.parser.CCJSqlParserUtil; import net.sf.jsqlparser.statement.select.Select; import net.sf.jsqlparser.util.TablesNamesFinder; import java.util.List; public class TestJSqlParserAll { public static void main(String[] args) throws Exception { String sql = "SELECT a.*, b.kode_barang AS kode_barang, b.qty_terima AS qty_terima, b.hrg_pokok AS harga_pokok FROM sch_erp_inventory.trh_penerimaan_lain a LEFT JOIN sch_erp_inventory.trd_penerimaan_lain b ON a.no_tran = b.no_tran WHERE a.kode_cabang = 'C001'"; Select select = (Select) CCJSqlParserUtil.parse(sql); TablesNamesFinder tablesNamesFinder = new TablesNamesFinder(); List<String> tableList = tablesNamesFinder.getTableList(select); System.out.println(tableList); } }
